shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c2b2;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --teal: #1d5c63;
    --font-serif-cn: 'Noto Serif SC', Georgia, serif;
    --font-sans-cn: 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif-en: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans-en: 'Inter', 'Noto Sans SC', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    overflow-x: hidden;
    font-family: var(--font-serif-cn);
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
  }

  /* Strict Language Switching */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 2px;
    border-radius: 1px;
    font-weight: 600;
  }

  /* Top Sticky Masthead */
  .wsj-masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line-strong);
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.75rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-cluster {
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
  }

  .wsj-logo {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .section-pill {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    border-left: 1px solid var(--line-strong);
    padding-left: 0.85rem;
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
  }

  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    padding: 0.35rem 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .article-hero {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 3px double var(--line-strong);
  }

  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.78rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 1.25rem;
    font-weight: 700;
  }

  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 24px;
    height: 2px;
    background: var(--accent);
  }

  .hero-title {
    font-family: var(--font-display);
    font-size: clamp(2.1rem, 4.2vw, 3.6rem);
    line-height: 1.18;
    color: var(--ink);
    font-weight: 800;
    max-width: 980px;
    margin-bottom: 1.5rem;
    letter-spacing: -0.015em;
  }

  :host([lang="zh-CN"]) .hero-title {
    font-family: var(--font-serif-cn);
    line-height: 1.28;
    letter-spacing: 0;
  }

  .hero-dek {
    font-size: clamp(1.08rem, 1.6vw, 1.32rem);
    line-height: 1.65;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
    font-weight: 400;
  }

  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans-en);
    font-size: 0.85rem;
    color: var(--muted);
  }

  .byline-name {
    color: var(--ink);
    font-weight: 700;
  }

  .meta-tags {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
  }

  .meta-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    background: var(--paper-card);
    border: 1px solid var(--line);
    padding: 0.25rem 0.6rem;
    color: var(--muted);
  }

  /* Executive Top Strip (Key Numbers Overview) */
  .exec-ribbon {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1.75rem 1.5rem;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
    border-bottom: 1px solid var(--line-strong);
    background: linear-gradient(180deg, rgba(243,239,230,0.45) 0%, rgba(250,248,244,0) 100%);
  }

  .ribbon-item {
    border-left: 2px solid var(--accent);
    padding-left: 1rem;
  }

  .ribbon-num {
    font-family: var(--font-mono);
    font-size: 1.65rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 0.3rem;
  }

  .ribbon-lbl {
    font-family: var(--font-sans-cn);
    font-size: 0.8rem;
    color: var(--muted);
    line-height: 1.4;
  }

  /* Main Editorial Grid Layout */
  .editorial-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3rem 1.5rem 5rem;
  }

  .chapter-block {
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 3.5rem;
    align-items: start;
    margin-bottom: 4rem;
  }

  .chapter-block.reverse-rail {
    grid-template-columns: 320px 1fr;
  }

  .prose-column {
    max-width: 680px;
  }

  .rail-column {
    position: sticky;
    top: 4.5rem;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Section Divider Banner */
  .chapter-header {
    grid-column: 1 / -1;
    border-top: 2px solid var(--ink);
    padding-top: 1rem;
    margin-bottom: 0.5rem;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.1em;
  }

  .chapter-title {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--ink);
  }

  :host([lang="zh-CN"]) .chapter-title {
    font-family: var(--font-serif-cn);
  }

  /* Prose Paragraphs */
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.9;
    color: var(--body);
    margin-bottom: 1.5rem;
    font-weight: 400;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    line-height: 1.82;
  }

  /* Lead Paragraph treatment (No ::first-letter on Chinese!) */
  .prose-p.lead-p {
    font-size: 1.26rem;
    line-height: 1.85;
    color: var(--ink);
    font-weight: 600;
    border-left: 4px solid var(--accent);
    padding-left: 1.25rem;
    margin-bottom: 1.75rem;
  }

  /* Question Bridge Callout (p2) */
  .prose-p.pivot-question {
    font-family: var(--font-display);
    font-style: italic;
    font-size: 1.3rem;
    color: var(--accent);
    background: var(--paper-card);
    padding: 1.1rem 1.4rem;
    border-left: 3px solid var(--ink);
    margin: 1.75rem 0;
  }

  :host([lang="zh-CN"]) .prose-p.pivot-question {
    font-family: var(--font-serif-cn);
    font-style: normal;
    font-weight: 700;
  }

  /* Primary Climactic Blockquote (used for split or whole canonical quote paragraphs) */
  blockquote.climactic-quote {
    margin: 2.25rem 0;
    padding: 1.75rem 2rem;
    background: var(--navy-bg);
    color: var(--paper);
    border-left: 5px solid var(--accent);
    font-size: 1.25rem;
    line-height: 1.75;
    font-weight: 600;
    position: relative;
  }

  blockquote.climactic-quote::before {
    content: "“";
    font-family: var(--font-display);
    font-size: 3.5rem;
    color: var(--accent);
    position: absolute;
    top: 0.2rem;
    left: 0.6rem;
    opacity: 0.35;
    line-height: 1;
  }

  /* Derived Pull Quote Cards in Sidebar (`data-derive`) */
  .pull-quote {
    background: var(--paper-card);
    border-top: 3px solid var(--accent);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.5rem 1.35rem;
  }

  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.12rem;
    line-height: 1.65;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.85rem;
  }

  :host([lang="zh-CN"]) .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Derived Metric Cards (`data-derive`) */
  .metric-card {
    background: var(--ink);
    color: var(--paper);
    padding: 1.6rem 1.4rem;
    border-radius: 2px;
    border-top: 4px solid var(--accent);
  }

  .metric-val {
    font-family: var(--font-mono);
    font-size: 2.6rem;
    font-weight: 700;
    color: #f4a261;
    line-height: 1.05;
    margin-bottom: 0.5rem;
  }

  .metric-lbl {
    font-family: var(--font-sans-cn);
    font-size: 0.92rem;
    line-height: 1.5;
    color: var(--paper);
    margin-bottom: 0.65rem;
    font-weight: 500;
  }

  .metric-note {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: #a8a296;
    border-top: 1px solid rgba(255,255,255,0.15);
    padding-top: 0.55rem;
  }

  /* Editorial Dossier / Sidebar Card */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.4rem;
  }

  .dossier-head {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    font-weight: 700;
    padding-bottom: 0.6rem;
    margin-bottom: 1rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.9rem;
  }

  .dossier-list li {
    font-family: var(--font-sans-cn);
    font-size: 0.86rem;
    line-height: 1.55;
    color: var(--body);
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
  }

  .dossier-list strong {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--ink);
    text-transform: uppercase;
  }

  /* Bespoke Interactive SVG Exhibits */
  .exhibit-panel {
    grid-column: 1 / -1;
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 2px solid var(--ink);
    padding: 2.25rem 2rem;
    margin: 1rem 0 3.5rem;
  }

  .exhibit-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .exhibit-kicker {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.35rem;
  }

  .exhibit-title {
    font-family: var(--font-display);
    font-size: 1.45rem;
    color: var(--ink);
    font-weight: 700;
  }

  :host([lang="zh-CN"]) .exhibit-title {
    font-family: var(--font-serif-cn);
  }

  .exhibit-sub {
    font-family: var(--font-sans-cn);
    font-size: 0.88rem;
    color: var(--muted);
    max-width: 650px;
    margin-top: 0.25rem;
  }

  .svg-wrapper {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 1rem;
  }

  .exhibit-caption-block {
    margin-top: 1rem;
    padding-top: 0.85rem;
    border-top: 1px dashed var(--line-strong);
    font-family: var(--font-sans-cn);
    font-size: 0.85rem;
    color: var(--muted);
  }

  /* Photo Caption Canonical Block p22 styling */
  .canonical-caption {
    font-family: var(--font-sans-cn);
    font-size: 0.92rem;
    line-height: 1.6;
    color: var(--muted);
    background: var(--paper-card);
    border-left: 3px solid var(--ink);
    padding: 1rem 1.25rem;
    margin-top: 2rem;
  }

  /* Footer */
  .wsj-footer {
    border-top: 3px double var(--line-strong);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    text-align: center;
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .exec-ribbon {
      grid-template-columns: repeat(2, 1fr);
    }
    .chapter-block,
    .chapter-block.reverse-rail {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .rail-column {
      position: static;
    }
    .prose-column {
      max-width: 100%;
    }
    .exhibit-panel {
      padding: 1.5rem 1rem;
    }
  }

  @media (max-width: 540px) {
    .masthead-inner {
      padding: 0.65rem 1rem;
    }
    .section-pill {
      display: none;
    }
    .article-hero {
      padding: 2rem 1rem 1.75rem;
    }
    .exec-ribbon {
      grid-template-columns: 1fr;
      padding: 1.25rem 1rem;
    }
    .editorial-container {
      padding: 2rem 1rem 3.5rem;
    }
    .prose-p {
      font-size: 1.05rem;
      line-height: 1.82;
    }
    .prose-p.lead-p {
      font-size: 1.12rem;
    }
    blockquote.climactic-quote {
      padding: 1.35rem 1.25rem;
      font-size: 1.1rem;
    }
    .svg-wrapper {
      padding: 0.35rem;
    }
  }
